remediations.proposed_fix:
resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  mfa    = "arn:aws:iam::${var.account_id}:mfa/${var.root_mfa_device_name} ${var.mfa_otp_code}"
  versioning_configuration { status = "Enabled" 
    mfa_delete = "Enabled" }
}
# Apply only with root credentials; pass mfa_otp_code at runtime (ephemeral, never committed). Pair with an SCP denying s3:DeleteObjectVersion except for a break-glass role.

